INSERT INTO content (
     title
    ,body
    ,content_type
    ,visible_yn
    ,ordering
    ,content_link
    ,created_at
) VALUES

(
     IFNULL(#{item.safetyCateNm3}, '행동요령 참고 자료')
    ,#{item.body}
    ,#{contentType}
    ,'Y'
    ,#{item.ordering}
    ,#{item.contentsUrl}
    ,NOW()
)
